import Link from "next/link";
import { useEffect, useState } from "react";

export default function Home() {
  const [currentUser, setCurrentUser] = useState(undefined);

  useEffect(() => {
    const loadCurrentUser = async () => {
      try {
        const response = await fetch("/api/users/currentuser", {
          credentials: "include",
        });
        const data = await response.json();
        setCurrentUser(data.currentUser);
      } catch (err) {
        setCurrentUser(null);
      }
    };

    loadCurrentUser();
  }, []);

  return (
    <main className="page-shell">
      <nav className="top-nav">
        <Link href="/" className="brand">
          Ticketing
        </Link>
        <div className="nav-links">
          {currentUser ? (
            <Link href="/signout">Sign out</Link>
          ) : (
            <>
              <Link href="/signin">Sign in</Link>
              <Link href="/signup" className="nav-cta">
                Sign up
              </Link>
            </>
          )}
        </div>
      </nav>

      <section className="home-grid">
        <div className="home-copy">
          <p className="eyebrow">Microservices auth flow</p>
          <h1>Buy, sell, and manage tickets with a calmer login flow.</h1>
          <p className="lede">
            This client talks to the auth service through the ingress route at
            <code>/api/users</code>, including browser cookies for sessions.
          </p>
          <div className="actions">
            {currentUser ? (
              <Link href="/signout" className="button primary">
                Sign out
              </Link>
            ) : (
              <>
                <Link href="/signup" className="button primary">
                  Create account
                </Link>
                <Link href="/signin" className="button secondary">
                  Sign in
                </Link>
              </>
            )}
          </div>
        </div>

        <div className="status-panel">
          <span className="status-dot" />
          <p className="panel-label">Session status</p>
          {currentUser === undefined ? (
            <h2>Checking...</h2>
          ) : currentUser ? (
            <>
              <h2>Signed in</h2>
              <p>{currentUser.email}</p>
            </>
          ) : (
            <>
              <h2>Guest</h2>
              <p>No active session cookie found.</p>
            </>
          )}
        </div>
      </section>
    </main>
  );
}
